using METATOWebService;

/// <summary>
/// CB756_ValidationOfABNToATOSystem.
/// The <c>METATOWebServiceHelper</c> is an intermediary class that helps in getting date from ATO web service.
/// </summary>
class METATOWebServiceHelper
{
    CustTable     custTable;
    METWebService webService;
    str           entityName;
    METStatus     abnStatus;
    str           entityType;
    
}

Method.Source:
/// <summary>
/// Gets or sets table <c>CustTable</c>.
/// </summary>
/// <param name = "_custTable"> <c>CustTable</c>. .</param>
/// <returns> <c>CustTable</c>. </returns>
public CustTable parmCustTable(CustTable  _custTable = custTable)
{
    custTable = _custTable;
    return custTable;
}

/// <summary>
/// Gets and sets the entity name.
/// </summary>
/// <param name = "_entityName">Entity name.</param>
/// <returns>Entity name.</returns>
public str parmEntityName(str _entityName = entityName)
{
    entityName = _entityName;
    return entityName;
}

/// <summary>
/// Gets and sets the ABN status.
/// </summary>
/// <param name = "_abnStatus">ABN status.</param>
/// <returns>ABN status.</returns>
public METStatus parmABNStatus(METStatus _abnStatus = abnStatus)
{
    abnStatus = _abnStatus;
    return abnStatus;
}

/// <summary>
/// Gets and sets the entity type.
/// </summary>
/// <param name = "_entityType">Entity type.</param>
/// <returns>Entity type.</returns>
public str parmEntityType(str _entityType = entityType)
{
    entityType = _entityType;
    return entityType;
}

    /// <summary>
    /// Constructs and returns object of <c>METATOWebServiceHelper</c>.
    /// </summary>
    /// <param name = "_custTable"><c>CustTable</c>.</param>
    /// <returns> <c>METATOWebServiceHelper</c> object. </returns>
    public static METATOWebServiceHelper construct(CustTable _custTable)
    {
        METATOWebServiceHelper metATOWebServiceHelper = new METATOWebServiceHelper();

        metATOWebServiceHelper.parmCustTable(_custTable);
        metATOWebServiceHelper.init();

        return metATOWebServiceHelper;
    }

    /// <summary>
    /// Initializes <c>METATOWebServiceHelper</c>.
    /// </summary>
    public void init()
    {
        METCustParameters custParameter;

        custParameter = METCustParameters::Find();

        if (!custParameter.ABNValidationURL)
        {
            throw error("@MET:ABNValidationURLNotSetError");
        }

        if (!custParameter.ABNValidationGUID)
        {
            throw error("@MET:ABNValidationGUIDNotSetError");
        }

        webService = new METWebService(custParameter.ABNValidationURL, custParameter.ABNValidationGUID) ;
    }

    /// <summary>
    /// Calls the web service.
    /// </summary>
    /// <param name = "_searchText">Search text for the web service.</param>
    /// <returns>True, if service called successfully; otherwise, false.</returns>
    public boolean callWebService(str _searchText)
    {
        str       exception;
        str       abnStatusStr;
        boolean   isSuccess;

        webService.callService(_searchText);

        if (!webService.isError())
        {
            entityName   = webService.getEntityName();
            entityType   = webService.getEntityType();
            abnStatusStr = webService.getABNStatus();
            abnStatus    = str2Enum(abnStatus, abnStatusStr);

            isSuccess = true;
        }
        else
        {
            exception = webService.getException();
            error(strFmt("@MET:ATOWebServiceError", custTable.AccountNum, exception));
        }

        return isSuccess;
    }

    /// <summary>
    /// Updates table <c>TaxVATNumTable</c>.
    /// </summary>
    /// <param name = "_taxVATNumTable">Table <c>TaxVATNumTable</c>.</param>
    public void updateTaxVATNumTable(TaxVATNumTable _taxVATNumTable)
    {
        if (_taxVATNumTable.RecId)
        {
            ttsbegin;

            _taxVATNumTable.selectForUpdate(true);

            _taxVATNumTable.METEntityType   = entityType;
            _taxVATNumTable.METStatus       = abnStatus;
            _taxVATNumTable.Name            = entityName;
            _taxVATNumTable.METVerifiedDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            
            _taxVATNumTable.update();

            ttscommit;
        }
    }

    /// <summary>
    /// Updates table <c>TaxRegistration</c>.
    /// </summary>
    /// <param name = "_taxRegistration"> <c>TaxRegistration</c>. </param>
    public void updateTaxRegistration(TaxRegistration _taxRegistration)
    {
        if (_taxRegistration.RecId)
        {
            ttsbegin;
            
            _taxRegistration.selectForUpdate(true);

            _taxRegistration.Section         = entityType;
            _taxRegistration.METStatus       = abnStatus;
            _taxRegistration.Description     = entityName;
            _taxRegistration.METVerifiedDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

            _taxRegistration.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
            _taxRegistration.update();

            ttscommit;
        }
    }
